import os
import numpy as np

working_dir = os.path.join(os.getcwd(), "working")
experiment_data = np.load(
    os.path.join(working_dir, "experiment_data.npy"), allow_pickle=True
).item()

for dataset_name, data in experiment_data.items():
    print(f"Dataset: {dataset_name}")

    base_asr = data.get("asr", {}).get("base")
    rr_asr = data.get("asr", {}).get("rr")
    base_coh = data.get("coherence", {}).get("base")
    rr_coh = data.get("coherence", {}).get("rr")
    benign_coh = data.get("benign_coherence")

    if base_asr is not None:
        print(f"  Base Model Attack Success Rate (ASR): {base_asr:.4f}")
    if rr_asr is not None:
        print(f"  RR Model Attack Success Rate (ASR): {rr_asr:.4f}")
    if base_coh is not None:
        print(f"  Base Model Harmful Prompt Coherence: {base_coh:.4f}")
    if rr_coh is not None:
        print(f"  RR Model Harmful Prompt Coherence: {rr_coh:.4f}")
    if benign_coh is not None:
        print(f"  RR Model Benign Prompt Coherence: {benign_coh:.4f}")

    train_losses = data.get("losses", {}).get("train", [])
    if train_losses:
        print(f"  Final RR Training Loss: {float(train_losses[-1]):.4f}")
        print(
            f"  Mean RR Training Loss (last 20 steps): {float(np.mean(train_losses[-20:])):.4f}"
        )

    val_losses = data.get("losses", {}).get("val", [])
    if val_losses:
        print(f"  Final RR Validation Loss (proxy): {float(val_losses[-1]):.4f}")

    val_metrics = data.get("metrics", {}).get("val", [])
    if val_metrics:
        final_val = val_metrics[-1]
        if isinstance(final_val, dict):
            if "asr" in final_val:
                print(f"  Final Validation ASR: {final_val['asr']:.4f}")
            if "coherence" in final_val:
                print(f"  Final Validation Coherence: {final_val['coherence']:.4f}")

    train_loss_steps = data.get("train_loss_steps", [])
    if train_loss_steps:
        last = train_loss_steps[-1]
        if isinstance(last, dict):
            if "l_harm" in last:
                print(
                    f"  Final RR Harmful Representation Loss (l_harm): {last['l_harm']:.4f}"
                )
            if "l_retain" in last:
                print(
                    f"  Final RR Retain Representation Loss (l_retain): {last['l_retain']:.4f}"
                )

