import os
import numpy as np

working_dir = os.path.join(os.getcwd(), "working")
data_path = os.path.join(working_dir, "experiment_data.npy")

experiment_data = np.load(data_path, allow_pickle=True).item()

for dataset_name, data in experiment_data.items():
    print(f"Dataset: {dataset_name}")

    train_losses = data.get("losses", {}).get("train", [])
    val_losses = data.get("losses", {}).get("val", [])

    if train_losses:
        print(f"  Final training loss: {train_losses[-1]:.4f}")
        print(f"  Best (min) training loss: {min(train_losses):.4f}")

    if val_losses:
        print(f"  Final validation loss: {val_losses[-1]:.4f}")
        print(f"  Best (min) validation loss: {min(val_losses):.4f}")

    asr = data.get("asr", {})
    base_asr = asr.get("base", None)
    rr_asr = asr.get("rr", None)

    if base_asr is not None:
