def load_harmbench():
    prompts = []
    for pat in ["harmbench", "HarmBench"]:
        for root in [DATA_DIR, os.path.join(DATA_DIR, pat)]:
            for p in glob.glob(os.path.join(root, "**", "*.csv"), recursive=True):
                if "harmbench" in p.lower() and (
                    "behaviors" in p.lower()
                    or "test" in p.lower()
                    or "eval" in p.lower()
                ):
                    try:
                        import pandas as pd

                        df = pd.read_csv(p)
                        col = next(
                            (
                                c
                                for c in df.columns
                                if c.lower()
                                in [
                                    "behavior",
                                    "prompt",
                                    "goal",
                                    "query",
                                    "instruction",
                                ]
                            ),
                            None,
                        )
                        if col:
                            for v in df[col].dropna().tolist():
                                prompts.append(str(v).strip())
                    except Exception:
                        pass
            for p in glob.glob(os.path.join(root, "**", "*.json*"), recursive=True):
                if "harmbench" in p.lower():
                    try:
                        with open(p) as f:
                            txt = f.read()
                        try:
                            data = json.loads(txt)
                        except Exception:
                            data = [
                                json.loads(l)
                                for l in txt.strip().split("\n")
                                if l.strip()
                            ]
                        if isinstance(data, dict):
                            data = (
                                data.get("behaviors")
                                or data.get("data")
                                or list(data.values())[0]
                            )
                        if isinstance(data, list):
                            for item in data:
                                if isinstance(item, dict):
                                    v = (
                                        item.get("behavior")
                                        or item.get("prompt")
                                        or item.get("goal")
                                        or item.get("query")
                                    )
                                    if v:
                                        prompts.append(str(v).strip())
                                elif isinstance(item, str):
                                    prompts.append(item.strip())
                    except Exception:
                        pass
    return list(dict.fromkeys(prompts))


