        print(f"  Final Training Harm Loss: {final_entry['harm_loss']:.4f}")
        print(
            f"  Final Training Retain Cross-Entropy Loss: {final_entry['retain_ce']:.4f}"
        )
        print(
            f"  Final Training Representation Diff Loss: {final_entry['rep_diff']:.4f}"
        )

        min_harm = min(e["harm_loss"] for e in loss_log)
        min_retain_ce = min(e["retain_ce"] for e in loss_log)
        min_rep_diff = min(e["rep_diff"] for e in loss_log)
        print(f"  Minimum Training Harm Loss: {min_harm:.4f}")
        print(f"  Minimum Training Retain Cross-Entropy Loss: {min_retain_ce:.4f}")
        print(f"  Minimum Training Representation Diff Loss: {min_rep_diff:.4f}")

    val_metrics = data.get("metrics", {}).get("val", [])
    if len(val_metrics) > 0:
        final_val = val_metrics[-1]
        if isinstance(final_val, dict):
            if "base_asr" in final_val:
                print(f"  Validation Base ASR (final): {final_val['base_asr']:.4f}")
            if "rr_asr" in final_val:
                print(f"  Validation RR ASR (final): {final_val['rr_asr']:.4f}")

    if benign_before is not None:
        print(f"  Benign Prompt Response Before RR Training: {benign_before}")
    if benign_after is not None:
        print(f"  Benign Prompt Response After RR Training: {benign_after}")

    samples_base = data.get("samples_base", [])
    samples_rr = data.get("samples_rr", [])
    if len(samples_base) > 0:
        base_sample_asr = np.mean([s["asr"] for s in samples_base])
        print(f"  Base Model Sample-Level ASR (stored samples): {base_sample_asr:.4f}")
    if len(samples_rr) > 0:
        rr_sample_asr = np.mean([s["asr"] for s in samples_rr])
        print(f"  RR Model Sample-Level ASR (stored samples): {rr_sample_asr:.4f}")

